ByteVector extract_subrange(uint index, uint length) {
    if (index >= data.size()) {
        return ByteVector();
    }

    uint end_index = std::min(index + length, static_cast<uint>(data.size()));
    ByteVector result;
    result.reserve(length);
    for (uint i = index; i < end_index; ++i) {
        result.push_back(data[i]);
    }
    return result;
}

ByteVector extractSubrange(uint index, uint length) {
    if (index >= data.size()) {
        return ByteVector();
    }

    uint endPos = std::min(index + length, static_cast<uint>(data.size()));
    ByteVector result;
    result.insert(result.begin(), data.begin() + index, data.begin() + endPos);
    return result;
}

